import axios from 'axios'

// ============================================
// FREE SPORTSCORE API (No key required)
// ============================================
const SPORTSCORE_URL = 'https://sportscore.com/api/v1'

// ============================================
// COMPETITIONS (Leagues)
// ============================================
export const COMPETITIONS = {
    PREMIER_LEAGUE: 'PL',
    LA_LIGA: 'PD',
    BUNDESLIGA: 'BL1',
    SERIE_A: 'SA',
    LIGUE_1: 'FL1',
    CHAMPIONS_LEAGUE: 'CL',
}

// ============================================
// GET LIVE MATCHES
// ============================================
export async function getLiveMatches() {
    try {
        const response = await axios.get(`${SPORTSCORE_URL}/football/matches/live`)
        return response.data || []
    } catch (error) {
        console.error('Live matches error:', error)
        return []
    }
}

// ============================================
// GET MATCHES BY DATE
// ============================================
export async function getMatchesByDate(date) {
    try {
        const response = await axios.get(`${SPORTSCORE_URL}/football/matches/date/${date}`)
        return response.data || []
    } catch (error) {
        console.error('Matches by date error:', error)
        return []
    }
}

// ============================================
// GET TODAY'S MATCHES
// ============================================
export async function getTodaysMatches(competition = 'PL') {
    try {
        const today = new Date().toISOString().split('T')[0]
        const response = await axios.get(`${SPORTSCORE_URL}/football/matches/date/${today}`)
        
        if (response.data && response.data.length > 0) {
            return response.data
        }
        
        // Fallback to sample matches
        return getSampleMatches()
        
    } catch (error) {
        console.error('Error fetching matches:', error)
        return getSampleMatches()
    }
}

// ============================================
// GET STANDINGS
// ============================================
export async function getStandings(league) {
    try {
        const response = await axios.get(`${SPORTSCORE_URL}/football/standings/${league}`)
        return response.data || []
    } catch (error) {
        console.error('Standings error:', error)
        return []
    }
}

// ============================================
// FORMAT MATCH FOR DISPLAY
// ============================================
export function formatMatch(match) {
    // If match is from SportScore API
    if (match.homeTeam && match.awayTeam) {
        return {
            id: match.id || `match-${Math.random()}`,
            matchId: match.id || `match-${Math.random()}`,
            homeTeam: {
                name: match.homeTeam?.name || 'Unknown',
                crest: match.homeTeam?.logo || null,
                badge: getTeamEmoji(match.homeTeam?.name)
            },
            awayTeam: {
                name: match.awayTeam?.name || 'Unknown',
                crest: match.awayTeam?.logo || null,
                badge: getTeamEmoji(match.awayTeam?.name)
            },
            league: match.league?.name || 'Unknown League',
            leagueId: match.league?.id || 'unknown',
            kickoff: match.kickoff || match.date || new Date().toISOString(),
            status: match.status || 'upcoming',
            score: {
                home: match.score?.home || 0,
                away: match.score?.away || 0
            },
            venue: match.venue || 'Unknown Venue',
            aiPrediction: generateAIPrediction(match)
        }
    }
    
    // Fallback for any other format
    return {
        id: match.id || `match-${Math.random()}`,
        matchId: match.id || `match-${Math.random()}`,
        homeTeam: {
            name: match.homeTeam?.name || match.homeTeam || 'Unknown',
            crest: match.homeTeam?.crest || null,
            badge: getTeamEmoji(match.homeTeam?.name || match.homeTeam)
        },
        awayTeam: {
            name: match.awayTeam?.name || match.awayTeam || 'Unknown',
            crest: match.awayTeam?.crest || null,
            badge: getTeamEmoji(match.awayTeam?.name || match.awayTeam)
        },
        league: match.league || match.competition?.name || 'Unknown League',
        leagueId: match.leagueId || match.competition?.id || 'unknown',
        kickoff: match.kickoff || match.date || match.utcDate || new Date().toISOString(),
        status: match.status || 'upcoming',
        score: {
            home: match.score?.home || match.score?.fullTime?.home || 0,
            away: match.score?.away || match.score?.fullTime?.away || 0
        },
        venue: match.venue || match.venueName || 'Unknown Venue',
        aiPrediction: generateAIPrediction(match)
    }
}

// ============================================
// GENERATE AI PREDICTION
// ============================================
function generateAIPrediction(match) {
    const homeScore = match.score?.home || match.score?.fullTime?.home || 0
    const awayScore = match.score?.away || match.score?.fullTime?.away || 0
    
    if (match.status === 'finished' || match.status === 'FT' || match.status === 'FINISHED') {
        return {
            result: {
                home: homeScore > awayScore ? 90 : 20,
                draw: homeScore === awayScore ? 80 : 15,
                away: awayScore > homeScore ? 90 : 20
            },
            confidence: 95,
            isFinished: true,
            actualScore: `${homeScore}-${awayScore}`
        }
    }
    
    const homeStrength = Math.random() * 0.4 + 0.3
    const awayStrength = Math.random() * 0.4 + 0.3
    
    let homeWin = Math.round((homeStrength / (homeStrength + awayStrength)) * 70 + 10)
    let awayWin = Math.round((awayStrength / (homeStrength + awayStrength)) * 70 + 10)
    let draw = 100 - homeWin - awayWin
    
    homeWin = Math.max(10, Math.min(80, homeWin))
    awayWin = Math.max(10, Math.min(80, awayWin))
    draw = Math.max(5, Math.min(40, draw))
    
    const total = homeWin + draw + awayWin
    if (total !== 100) {
        const diff = 100 - total
        homeWin += Math.round(diff / 2)
        awayWin += diff - Math.round(diff / 2)
    }
    
    return {
        result: {
            home: Math.max(10, Math.min(80, homeWin)),
